// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // a fresh participant claims an airdrop, shifting totalDistributed and totalRemaining apart
        vm.prank(actor);
        c.getTokens();
        // owner (re)initializes the sale
        c.NETM();
        // general rule: the owner's balance always equals totalDistributed after NETM()
        assertTrue(c.balanceOf(address(this)) == c.totalDistributed());
    }
}
